package middleware

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"net/http"

	gen "nerae/api/internal/gen"
)

var ErrResponseWrite = errors.New("cannot write error response")

// RequestID is generated by the service, not accepted from a client header.
// It can be shared with the server's redacted request logging when wired.
type RequestID struct{ value string }

func NewRequestID() (RequestID, error) {
	var random [16]byte
	if _, err := rand.Read(random[:]); err != nil {
		return RequestID{}, ErrContract
	}
	return RequestID{value: hex.EncodeToString(random[:])}, nil
}

func (id RequestID) String() string { return id.value }

type ErrorKind uint8

const (
	BadRequest ErrorKind = iota + 1
	Unauthenticated
	Forbidden
	NotFound
	Conflict
	UpgradeRequired
	VersionConflict
	ValidationError
	RateLimited
	Unavailable
	InternalError
)

type publicError struct {
	status  int
	code    string
	message string
}

func errorDetails(kind ErrorKind) publicError {
	switch kind {
	case BadRequest:
		return publicError{http.StatusBadRequest, "BAD_REQUEST", "请求格式有误"}
	case Unauthenticated:
		return publicError{http.StatusUnauthorized, "UNAUTHENTICATED", "请先登录"}
	case Forbidden:
		return publicError{http.StatusForbidden, "FORBIDDEN", "无法执行此操作"}
	case NotFound:
		return publicError{http.StatusNotFound, "NOT_FOUND", "未找到相关内容"}
	case Conflict:
		return publicError{http.StatusConflict, "CONFLICT", "状态已变化，请检查当前内容"}
	case UpgradeRequired:
		return publicError{http.StatusConflict, "CLIENT_UPGRADE_REQUIRED", "此记录需要更新应用后查看"}
	case VersionConflict:
		return publicError{http.StatusPreconditionFailed, "VERSION_CONFLICT", "记录已更新，请先查看最新内容"}
	case ValidationError:
		return publicError{http.StatusUnprocessableEntity, "VALIDATION_ERROR", "填写内容不符合要求"}
	case RateLimited:
		return publicError{http.StatusTooManyRequests, "RATE_LIMITED", "操作过于频繁，请稍后再试"}
	case Unavailable:
		return publicError{http.StatusServiceUnavailable, "SERVICE_UNAVAILABLE", "服务暂时不可用"}
	default:
		return publicError{http.StatusInternalServerError, "INTERNAL_ERROR", "服务暂时不可用"}
	}
}

// WriteError accepts no upstream error, caller-supplied message or details. It
// validates the wire response before writing and never exposes transport errors.
// The handler must decide the correct kind without comparing error strings.
func WriteError(w http.ResponseWriter, validator *SchemaValidator, id RequestID, kind ErrorKind) error {
	if w == nil || validator == nil || id.value == "" {
		return ErrResponseWrite
	}
	details := errorDetails(kind)
	body, err := validator.EncodeResponse("Error", gen.Error{
		Code: details.code, Message: details.message, RequestId: id.value,
	})
	if err != nil {
		return ErrResponseWrite
	}
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("X-Request-ID", id.value)
	w.WriteHeader(details.status)
	if n, err := w.Write(body); err != nil || n != len(body) {
		return ErrResponseWrite
	}
	return nil
}
